#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Post-merge SEO setup for clauze.tn (landing PR #1). Run from anywhere:
#   bash scripts/seo-setup-wizard.sh
# Order matters: canonical host first, then search engines, then IndexNow.

TOTAL_STAGES=7
SITE="https://clauze.tn"
LANDING_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

# http_line URL prints "<status> <location>" for one request (no redirects followed).
http_line() {
  curl -s -o /dev/null -m 20 -w '%{http_code} %{redirect_url}' "$1" || echo "000 (unreachable)"
}

# check URL EXPECTED_STATUS [LOCATION_PREFIX]: one verification line.
check() {
  local got status loc
  got=$(http_line "$1"); status=${got%% *}; loc=${got#* }
  if [[ "$status" == "$2" && ( -z "${3:-}" || "$loc" == "$3"* ) ]]; then
    printf '  %s✓%s %s → %s %s\n' "$GREEN" "$RESET" "$1" "$status" "$loc"
  else
    printf '  %s✗%s %s → %s %s %s(expected %s %s)%s\n' "$RED" "$RESET" "$1" "$status" "$loc" "$DIM" "$2" "${3:-}" "$RESET"
    return 1
  fi
}

banner "clauze.tn: SEO setup after the landing merge"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Landing PR merged and deployed"
say "Everything below assumes the SEO branch is live in production."
open_url "https://github.com/clausedgpt/clauze-landing-page/pull/1"
step "Merge PR #1 if it isn't merged yet, then wait for Vercel's production deploy to finish."
pause "Press Enter once the production deploy is green."
say "Checking that the new files are live (through whatever host serves today):"
until got=$(curl -sL -m 20 "$SITE/robots.txt") && [[ "$got" == *"Sitemap: https://clauze.tn/sitemap.xml"* ]]; do
  warn "robots.txt isn't the new one yet."
  confirm "Check again?" || { SKIPPED+=("confirm the SEO deploy is live (robots.txt)"); break; }
done
[[ "${got:-}" == *"Sitemap:"* ]] && printf '  %s✓%s new robots.txt is live\n' "$GREEN" "$RESET"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Vercel: make clauze.tn the primary domain"
say "Today clauze.tn redirects to www.clauze.tn, but every canonical tag says clauze.tn."
say "Flip it so www redirects to the apex."
open_url "https://vercel.com/dashboard"
step "Open the clauze-landing-page project → Settings → Domains."
step "On the www.clauze.tn row: Edit → set it to redirect to clauze.tn (308 Permanent) → Save."
step "On the clauze.tn row: Edit → make sure it has NO redirect (serves the production deployment) → Save."
note "Labels may differ slightly in Vercel's current UI; the goal is: apex serves, www redirects to apex."
pause "Press Enter when both rows are saved."
until check "https://www.clauze.tn/" 308 "https://clauze.tn/" && check "$SITE/" 307 && check "$SITE/fr" 200; do
  warn "Not there yet (Vercel can take a minute)."
  confirm "Check again?" || { SKIPPED+=("Vercel: www → apex redirect"); break; }
done
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Production smoke test"
say "Checking the crawler files and a few pages on the canonical host:"
ok=1
for u in /robots.txt /sitemap.xml /llms.txt /llms-full.txt /fr/fonctionnalites/assistant-juridique-ia /ar/features/legal-research /en/compare/clauze-vs-chatgpt /fr/opengraph-image /ar/compare/clauze-vs-chatgpt/opengraph-image /0148346594714100962af690948b3b8e.txt; do
  check "$SITE$u" 200 || ok=0
done
if [[ "$(curl -sI -m 20 "$SITE/fr" | tr -d '\r' | grep -i '^x-robots-tag' || true)" != "" ]]; then
  warn "Production sends an X-Robots-Tag header: is VERCEL_ENV really 'production' here?"; ok=0
fi
(( ok )) || SKIPPED+=("fix the failed production checks (stage 3)")
step "Optional: paste a page URL into https://www.opengraph.xyz to see the social card."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Google Search Console: verify the domain (DNS)"
say "A Domain property covers clauze.tn, www and app.clauze.tn in one go."
open_url "https://search.google.com/search-console/welcome"
step "Left box 'Domain' → type clauze.tn → Continue."
step "Google shows a TXT record like google-site-verification=XXXX. Copy it (Google keeps that dialog open)."
ask GSC_TXT "Paste the TXT value (google-site-verification=…):"
say "Now add it at the clauze.tn DNS provider (where the A/CNAME records for clauze.tn and app live):"
step "New record: type TXT, name/host @ (the bare clauze.tn), value: $GSC_TXT"
step "Keep any existing TXT records; this one is added alongside them."
pause "Press Enter once the record is saved."
until nslookup -type=TXT clauze.tn 8.8.8.8 2>/dev/null | grep -q "${GSC_TXT#google-site-verification=}"; do
  warn "Not visible in public DNS yet (can take minutes, sometimes an hour)."
  confirm "Check again?" || { SKIPPED+=("Search Console: DNS TXT not yet visible; click Verify later"); break; }
done
step "Back in Search Console, click Verify."
pause "Press Enter once Search Console says ownership is verified."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Google Search Console: submit the sitemap"
open_url "https://search.google.com/search-console/sitemaps?resource_id=sc-domain:clauze.tn"
step "Under 'Add a new sitemap', the field is prefixed with https://clauze.tn/; type sitemap.xml → Submit."
step "Status should become 'Success' with 48 discovered pages (it may say 'Couldn't fetch' for a few minutes)."
note "Optional: URL inspection → https://clauze.tn/fr → Request indexing, to speed up the first crawl."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Bing Webmaster Tools: import from Search Console"
say "Bing also feeds ChatGPT search and Copilot, so it matters for GEO."
open_url "https://www.bing.com/webmasters"
step "Sign in (a Microsoft or Google account works)."
step "Choose 'Import your sites from GSC' → Continue → allow access → select sc-domain:clauze.tn → Import."
step "Importing brings the verification and the sitemap across, so no DNS record is needed."
step "Check Sitemaps in Bing: https://clauze.tn/sitemap.xml should be listed (submit it there if not)."
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "IndexNow: announce every URL"
say "Pings IndexNow (Bing, Yandex, Seznam…) with every URL in the live sitemap."
if confirm "Run 'pnpm indexnow' now?"; then
  if (cd "$LANDING_DIR" && pnpm indexnow); then
    printf '  %s✓%s IndexNow accepted the submission (200/202)\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("IndexNow: re-run 'pnpm indexnow' in clauze-landing-page (a 403 means the key file isn't live yet)")
  fi
else
  SKIPPED+=("IndexNow: run 'pnpm indexnow' in clauze-landing-page")
fi
note "Re-run 'pnpm indexnow' after any production deploy that changes pages."
pause

finish
